def point_set(intervals):
    pts = set()
    for s, e in intervals:
        pts.update(range(s, e + 1))
    return pts

def reference_merge(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError
    if not intervals:
        return []
    ivs = sorted(intervals)
    out = [ivs[0]]
    for s, e in ivs[1:]:
        ps, pe = out[-1]
        if s <= pe:  # overlap or touch (share a point); adjacent s == pe+1 stays separate
            out[-1] = (ps, max(pe, e))
        else:
            out.append((s, e))
    return out

