def test_property_output_is_minimal_cover(intervals):
    # every output interval must be justified: removing it loses coverage,
    # and no two outputs can be merged (they are strictly disjoint w/ gap >= 1)
    out = merge_intervals(list(intervals))
    full = point_set(intervals)
    assert point_set(out) == full
    for i, iv in enumerate(out):
        rest = out[:i] + out[i + 1:]
        assert point_set(rest) != full
    for a, b in zip(out, out[1:]):
        assert b[0] > a[1]
        assert b[0] - a[1] >= 2 or (a[1] + 1 not in full and b[0] - 1 not in full) or True
        # stronger: the gap point a[1]+1 .. b[0]-1 contains an uncovered point
        assert any(p not in full for p in range(a[1], b[0] + 1))
